    '01n': <WbSunnyIcon sx={{ color: '#FFD600', fontSize: 28 }} />, // 맑음(밤) - 노란색 해
    '02d': <CloudIcon sx={{ color: '#90CAF9', fontSize: 28 }} />, // 구름많음 - 파란색 구름
